package com.veer.maya;
import android.content.*;import android.net.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.*;import java.util.concurrent.*;
public class MayaCore{static ExecutorService ex=Executors.newSingleThreadExecutor();static String P="maya_ai",K="key";static String key(Context c){return c.getSharedPreferences(P,0).getString(K,"");}public static void saveKey(Context c,String k){c.getSharedPreferences(P,0).edit().putString(K,k.trim()).apply();}
public static void process(Context c,String u){Context a=c.getApplicationContext();MayaMemory.add(a,"user",u);if(key(a).isEmpty()){reply(a,"पहले API key save करो।");return;}ex.execute(()->{try{JSONObject q=new JSONObject();q.put("model","gpt-5.6-luna");q.put("instructions","You are MAYA Android assistant. Return ONLY JSON: {say:string,memory:array,actions:array}. Actions: open_app{name},tap{text},type{text},scroll{direction},back,home,recent,web_search{query},dial{number},message{number,text}. Calls/messages need confirmation. Use concise Hindi/Hinglish.");q.put("input","MEMORY="+MayaMemory.get(a)+"\nUSER="+u);HttpURLConnection h=(HttpURLConnection)new URL("https://api.openai.com/v1/responses").openConnection();h.setRequestMethod("POST");h.setRequestProperty("Authorization","Bearer "+key(a));h.setRequestProperty("Content-Type","application/json");h.setDoOutput(true);h.getOutputStream().write(q.toString().getBytes(StandardCharsets.UTF_8));int code=h.getResponseCode();BufferedReader r=new BufferedReader(new InputStreamReader(code>=400?h.getErrorStream():h.getInputStream()));StringBuilder s=new StringBuilder();String z;while((z=r.readLine())!=null)s.append(z);if(code>=400){reply(a,"AI error "+code);return;}String out=text(new JSONObject(s.toString()));JSONObject j=new JSONObject(out);String say=j.optString("say","ठीक है।");JSONArray m=j.optJSONArray("memory"),acts=j.optJSONArray("actions");if(m!=null)for(int i=0;i<m.length();i++)MayaMemory.add(a,"memory",m.optString(i));if(acts==null)acts=new JSONArray();boolean hi=false;for(int i=0;i<acts.length();i++){String t=acts.getJSONObject(i).optString("type");if(t.equals("dial")||t.equals("message")){hi=true;break;}}if(hi){reply(a,say+"\nइस action के लिए MAYA में confirmation चाहिए।");}else{run(a,acts);reply(a,say);}}catch(Exception e){reply(a,"MAYA AI connection में समस्या है।");}});}
static String text(JSONObject r){try{JSONArray o=r.optJSONArray("output");for(int i=0;i<o.length();i++){JSONArray c=o.getJSONObject(i).optJSONArray("content");for(int j=0;j<c.length();j++){JSONObject x=c.getJSONObject(j);if(x.optString("type").equals("output_text"))return x.optString("text");}}}catch(Exception e){}return "{\"say\":\"Response नहीं मिला\",\"memory\":[],\"actions\":[]}";}
static void run(Context c,JSONArray a){Handler h=new Handler(Looper.getMainLooper());for(int i=0;i<a.length();i++){final int n=i;h.postDelayed(()->{try{one(c,a.getJSONObject(n));}catch(Exception e){}},i*800L);}}static void one(Context c,JSONObject a)throws Exception{String t=a.optString("type");MayaAccessibilityService s=MayaAccessibilityService.getInstance();if(t.equals("open_app")){if(s!=null)s.executeCommand("open "+a.optString("name"));}else if(t.equals("tap")){if(s!=null)s.executeCommand("tap "+a.optString("text"));}else if(t.equals("type")){if(s!=null)s.executeCommand("type "+a.optString("text"));}else if(t.equals("scroll")){if(s!=null)s.executeCommand("scroll "+a.optString("direction"));}else if(t.equals("back")||t.equals("home")||t.equals("recent")){if(s!=null)s.executeCommand(t);}else if(t.equals("web_search")){Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/search?q="+Uri.encode(a.optString("query"))));i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);}}static void reply(Context c,String s){MayaMemory.add(c,"assistant",s);Intent i=new Intent("com.veer.maya.REPLY");i.setPackage(c.getPackageName());i.putExtra("text",s);c.sendBroadcast(i);MayaVoiceService.say(s);}}